	if not validator:
		return false
	var invalid_lines: Array = [
		{"type": "line", "speaker": "MagoMisterioso", "text": "Chi osa disturbarmi?"}
	]
	var errors := validator.validate_lines(invalid_lines, "test_speaker.json")
	if errors.is_empty():
		return false
	for err in errors:
		if err.contains("MagoMisterioso") or err.to_lower().contains("sconosciuto"):
			return true
	return false


